import { ethers, sendTx, requireSelf, getProvider } from './contracts.js';
import { CONTRACTS } from './chain-config.js';
import { get } from './store.js';
import { permissionlessReadProvider } from './read-provider.js';
import { loadSchema } from '../chain/schema.js';

const MAX_UINT256 = (1n << 256n) - 1n;
let factory;
const pending = new Set();
const lower = value => String(value ?? '').toLowerCase();
export function __setLoanFactoryForTest(value) { factory = value; }
async function contracts(runner) {
  if (factory) return factory(runner);
  const [game, lens] = await Promise.all([loadSchema('GAME'), loadSchema('GAME_LENS')]);
  return { game: new ethers.Contract(CONTRACTS.GAME, game.abi, runner),
    lens: new ethers.Contract(CONTRACTS.GAME_LENS, lens.abi, runner) };
}
const uint = (value, max, label) => {
  const n = Number(value);
  if (!Number.isSafeInteger(n) || n <= 0 || n > max) throw new Error(`Invalid ${label}.`);
  return n;
};
function ownerGate(player) {
  requireSelf();
  if (get('ui.mode') !== 'self' || lower(player) !== lower(get('connected.address'))) {
    throw new Error('Connect the account owner wallet.');
  }
}
async function readAccount(c, player, accountId) {
  const id = accountId == null ? Number(await c.game.walletIdOf_g3120(player)) : uint(accountId, 0xffffffff, 'account ID');
  if (!id) return { supported: true, accountId: 0, principal: 0n, owed: 0n };
  const [account, loan, balances, level, ticketLevel] = await Promise.all([
    c.game.resolveAccount_g7029(id, player), c.lens.loanOf(CONTRACTS.GAME, id),
    c.lens.accountBalances(CONTRACTS.GAME, id), c.game.currentLvl(), c.lens.activeTicketLevelOf(CONTRACTS.GAME),
  ]);
  const claimable = BigInt(balances.claimable ?? balances[0]);
  return { supported: true, accountId: id, payee: lower(account.payee ?? account[1]),
    level: Number(level), maxDueLevel: Number(ticketLevel) + 98,
    principal: BigInt(loan.principal ?? loan[0]), lenderId: Number(loan.lenderId ?? loan[1]),
    startLevel: Number(loan.startLevel ?? loan[2]), dueLevel: Number(loan.dueLevel ?? loan[3]),
    family: Number(loan.family ?? loan[4]), owed: BigInt(loan.owed ?? loan[5]),
    claimable: claimable > 0n ? claimable - 1n : 0n };
}
export async function readAccountLoan({ player, accountId } = {}) {
  if (!ethers.isAddress(player)) throw new Error('Choose a player wallet.');
  return readAccount(await contracts(permissionlessReadProvider(getProvider())), player, accountId);
}
async function readQuote(c, id, dueLevel, amount) {
  const raw = await c.lens.previewBorrow(CONTRACTS.GAME, id, dueLevel, amount);
  const principal = BigInt(raw.principal ?? raw[5]), ticketWei = BigInt(raw.ticketWei ?? raw[6]);
  return { accountId: Number(raw.accountId ?? raw[0]), lenderId: Number(raw.lenderId ?? raw[1]),
    eligible: Boolean(raw.eligible ?? raw[2]), face: BigInt(raw.face ?? raw[3]),
    maxPrincipal: BigInt(raw.maxPrincipal ?? raw[4]), principal, ticketWei, ethOut: principal - ticketWei };
}
export async function previewAccountLoan({ player, accountId, dueLevel, amount = MAX_UINT256 } = {}) {
  const c = await contracts(permissionlessReadProvider(getProvider()));
  const account = await readAccount(c, player, accountId);
  if (!account.accountId) throw new Error('This wallet has no game account.');
  const due = uint(dueLevel, 0xffffff, 'due level'), value = BigInt(amount);
  if (value <= 0n) throw new Error('Choose a positive loan amount.');
  return { ...await readQuote(c, account.accountId, due, value), payee: account.payee, dueLevel: due, supported: true };
}
async function writeFor(player, id, label, build) {
  ownerGate(player);
  const key = `${lower(CONTRACTS.GAME)}:${id}`;
  if (pending.has(key)) throw new Error('An account transaction is already pending.');
  pending.add(key);
  try {
    const receipt = await sendTx(async signer => {
      const owner = lower(await signer.getAddress());
      ownerGate(player);
      if (owner !== lower(player)) throw new Error('The wallet changed. Refresh the account.');
      const c = await contracts(signer);
      const account = await readAccount(c, player, id);
      if (account.payee !== owner) throw new Error('Only the account owner can do this.');
      return build(c, account, () => ownerGate(player));
    }, label);
    return { receipt, accountId: id };
  } finally { pending.delete(key); }
}
export async function borrowAgainstAccount({ player, accountId, dueLevel, amount, minEthOut } = {}) {
  const id = uint(accountId, 0xffffffff, 'account ID'), due = uint(dueLevel, 0xffffff, 'due level');
  const value = BigInt(amount ?? 0), minimum = BigInt(minEthOut ?? 0);
  if (id <= 3 || value <= 0n || minimum <= 0n || minimum > value) throw new Error('Refresh a valid loan quote first.');
  return writeFor(player, id, 'Borrow against account', async (c, account, gate) => {
    if (account.principal) throw new Error('This account already has a loan.');
    const quote = await readQuote(c, id, due, value);
    if (!quote.eligible || quote.accountId !== id || quote.principal !== value || quote.ethOut < minimum) {
      throw new Error('The loan offer changed or is unavailable. Refresh the quote.');
    }
    await c.game.borrow.staticCall(id, due, value, minimum);
    gate();
    return c.game.borrow(id, due, value, minimum);
  });
}
export async function repayAccountLoan({ player, accountId, maxOwed } = {}) {
  const id = uint(accountId, 0xffffffff, 'account ID'), maximum = BigInt(maxOwed ?? 0);
  return writeFor(player, id, 'Repay account loan', async (c, account, gate) => {
    if (!account.principal || account.owed <= 0n || account.level >= account.dueLevel) throw new Error('This loan is no longer repayable. Refresh the account.');
    if (account.owed > maximum) throw new Error('The repayment increased. Refresh before repaying.');
    const value = account.owed > account.claimable ? account.owed - account.claimable : 0n;
    await c.game.clearDebtNow.staticCall(id, { value });
    gate();
    return c.game.clearDebtNow(id, { value });
  });
}
export async function sweepSubaccounts({ player, accountIds } = {}) {
  ownerGate(player);
  const ids = [...new Set((accountIds ?? []).map(id => uint(id, 0xffffffff, 'account ID')))];
  if (!ids.length || ids.length > 32) throw new Error('Choose between 1 and 32 subaccounts.');
  return sendTx(async signer => {
    ownerGate(player);
    if (lower(await signer.getAddress()) !== lower(player)) throw new Error('The wallet changed.');
    const c = await contracts(signer);
    await c.game.sweepAccounts.staticCall(ids);
    ownerGate(player);
    return c.game.sweepAccounts(ids);
  }, 'Collect subaccount balances');
}
